var QRCode;
(function () {
	function QRCode(el, vOption) {
		this._htOption = {
			width: 256,
			height: 256,
			typeNumber: 4,
			colorDark: "#000000",
			colorLight: "#ffffff",
			correctLevel: QRErrorCorrectLevel.H
		};

		if (typeof vOption === 'string') {
			vOption = {
				text: vOption
			};
		}

		if (vOption) {
			for (var i in vOption) {
				this._htOption[i] = vOption[i];
			}
		}

		if (typeof el == "string") {
			el = document.getElementById(el);
		}

		this._el = el;
		this._oQRCode = null;
		this.makeCode(this._htOption.text);
	}

	QRCode.prototype.makeCode = function (sText) {
		this._oQRCode = new QRCodeModel(_getTypeNumber(sText, this._htOption.correctLevel), this._htOption.correctLevel);
		this._oQRCode.addData(sText);
		this._oQRCode.make();
		this.render();
	};

	QRCode.prototype.render = function () {
		var _el = this._el;
		var _htOption = this._htOption;
		var _oQRCode = this._oQRCode;

		if (!_el) return;
		_el.innerHTML = "";
		
		var canvas = document.createElement("canvas");
		canvas.width = _htOption.width;
		canvas.height = _htOption.height;
		var ctx = canvas.getContext("2d");

		var nCount = _oQRCode.getModuleCount();
		var nWidth = _htOption.width / nCount;
		var nHeight = _htOption.height / nCount;

		for (var row = 0; row < nCount; row++) {
			for (var col = 0; col < nCount; col++) {
				var bIsDark = _oQRCode.isDark(row, col);
				ctx.fillStyle = bIsDark ? _htOption.colorDark : _htOption.colorLight;
				ctx.fillRect(Math.round(col * nWidth), Math.round(row * nHeight), Math.ceil(nWidth), Math.ceil(nHeight));
			}
		}
		_el.appendChild(canvas);
	};

	// ── Módulos Internos QRCode ───────────────────────────────────
	function QRCodeModel(typeNumber, errorCorrectLevel) {
		this.typeNumber = typeNumber;
		this.errorCorrectLevel = errorCorrectLevel;
		this.modules = null;
		this.moduleCount = 0;
		this.dataCache = null;
		this.dataList = [];
	}

	QRCodeModel.prototype = {
		addData: function (data) { var newData = new QR8bitByte(data); this.dataList.push(newData); this.dataCache = null; },
		isDark: function (row, col) { return this.modules[row][col]; },
		getModuleCount: function () { return this.moduleCount; },
		make: function () { this.makeImpl(false, 0); },
		makeImpl: function (test, maskPattern) {
			this.moduleCount = this.typeNumber * 4 + 17;
			this.modules = new Array(this.moduleCount);
			for (var row = 0; row < this.moduleCount; row++) {
				this.modules[row] = new Array(this.moduleCount);
				for (var col = 0; col < this.moduleCount; col++) { this.modules[row][col] = null; }
			}
			this.setupPositionProbePattern(0, 0);
			this.setupPositionProbePattern(this.moduleCount - 7, 0);
			this.setupPositionProbePattern(0, this.moduleCount - 7);
			this.setupTimingPattern();
			this.setupPositionAdjustmentPattern();
			this.setupTypeInfo(test, maskPattern);
			this.mapData(QRUtil.createData(this.typeNumber, this.errorCorrectLevel, this.dataList), maskPattern);
		},
		setupPositionProbePattern: function (row, col) {
			for (var r = -1; r <= 7; r++) {
				for (var c = -1; c <= 7; c++) {
					if (row + r <= -1 || this.moduleCount <= row + r || col + c <= -1 || this.moduleCount <= col + c) continue;
					if ((0 <= r && r <= 6 && (c == 0 || c == 6)) || (0 <= c && c <= 6 && (r == 0 || r == 6)) || (2 <= r && r <= 4 && 2 <= c && c <= 4)) {
						this.modules[row + r][col + c] = true;
					} else { this.modules[row + r][col + c] = false; }
				}
			}
		},
		setupTimingPattern: function () {
			for (var r = 8; r < this.moduleCount - 8; r++) { if (this.modules[r][6] != null) continue; this.modules[r][6] = (r % 2 == 0); }
			for (var c = 8; c < this.moduleCount - 8; c++) { if (this.modules[6][c] != null) continue; this.modules[6][c] = (c % 2 == 0); }
		},
		setupPositionAdjustmentPattern: function () {
			var pos = QRUtil.getPatternPosition(this.typeNumber);
			for (var i = 0; i < pos.length; i++) {
				for (var j = 0; j < pos.length; j++) {
					var row = pos[i], col = pos[j];
					if (this.modules[row][col] != null) continue;
					for (var r = -2; r <= 2; r++) {
						for (var c = -2; c <= 2; c++) {
							if (r == -2 || r == 2 || c == -2 || c == 2 || (r == 0 && c == 0)) { this.modules[row + r][col + c] = true; } 
							else { this.modules[row + r][col + c] = false; }
						}
					}
				}
			}
		},
		setupTypeInfo: function (test, maskPattern) {
			var data = (this.errorCorrectLevel << 3) | maskPattern;
			var bits = QRUtil.getBCHTypeInfo(data);
			for (var i = 0; i < 15; i++) {
				var mod = (!test && ((bits >> i) & 1) == 1);
				if (i < 6) { this.modules[i][8] = mod; } 
				else if (i < 8) { this.modules[i + 1][8] = mod; } 
				else { this.modules[this.moduleCount - 15 + i][8] = mod; }
			}
			for (var i = 0; i < 15; i++) {
				var mod = (!test && ((bits >> i) & 1) == 1);
				if (i < 8) { this.modules[8][this.moduleCount - i - 1] = mod; } 
				else if (i < 9) { this.modules[8][15 - i - 1 + 1] = mod; } 
				else { this.modules[8][15 - i - 1] = mod; }
			}
			this.modules[this.moduleCount - 8][8] = (!test);
		},
		mapData: function (data, maskPattern) {
			var inc = -1, row = this.moduleCount - 1, bitIndex = 7, byteIndex = 0;
			for (var col = this.moduleCount - 1; col > 0; col -= 2) {
				if (col == 6) col--;
				while (true) {
					for (var c = 0; c < 2; c++) {
						if (this.modules[row][col - c] == null) {
							var dark = false;
							if (byteIndex < data.length) { dark = (((data[byteIndex] >>> bitIndex) & 1) == 1); }
							var mask = QRUtil.getMask(maskPattern, row, col - c);
							if (mask) { dark = !dark; }
							this.modules[row][col - c] = dark;
							bitIndex--;
							if (bitIndex == -1) { byteIndex++; bitIndex = 7; }
						}
					}
					row += inc;
					if (row < 0 || this.moduleCount <= row) { row -= inc; inc = -inc; break; }
				}
			}
		}
	};

	function QR8bitByte(data) { this.mode = QRMode.MODE_8BIT_BYTE; this.data = data; }
	QR8bitByte.prototype = {
		getLength: function (buffer) { return this.data.length; },
		write: function (buffer) { for (var i = 0; i < this.data.length; i++) { buffer.put(this.data.charCodeAt(i), 8); } }
	};

	var QRMode = { MODE_8BIT_BYTE: 4 };
	var QRErrorCorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };
	var QRUtil = {
		PATTERN_POSITION_TABLE: [[], [6, 18], [6, 22], [6, 26], [6, 30], [6, 34], [6, 22, 38], [6, 24, 42], [6, 26, 46]],
		getBCHTypeInfo: function (data) { var d = data << 10; while (QRUtil.getBCHDigit(d) - QRUtil.getBCHDigit(1335) >= 0) { d ^= (1335 << (QRUtil.getBCHDigit(d) - QRUtil.getBCHDigit(1335))); } return ((data << 10) | d) ^ 21522; },
		getBCHDigit: function (data) { var digit = 0; while (data != 0) { digit++; data >>>= 1; } return digit; },
		getPatternPosition: function (typeNumber) { return QRUtil.PATTERN_POSITION_TABLE[typeNumber - 1]; },
		getMask: function (maskPattern, i, j) {
			switch (maskPattern) {
				case 0: return (i + j) % 2 == 0;
				case 1: return i % 2 == 0;
				case 2: return j % 3 == 0;
				case 3: return (i + j) % 3 == 0;
				case 4: return (Math.floor(i / 2) + Math.floor(j / 3)) % 2 == 0;
				case 5: return (i * j) % 2 + (i * j) % 3 == 0;
				case 6: return ((i * j) % 2 + (i * j) % 3) % 2 == 0;
				case 7: return ((i * j) % 3 + (i + j) % 2) % 2 == 0;
				default: throw new Error("bad maskPattern:" + maskPattern);
			}
		},
		createData: function (typeNumber, errorCorrectLevel, dataList) {
			var buffer = new QRBitBuffer();
			for (var i = 0; i < dataList.length; i++) {
				var data = dataList[i];
				buffer.put(data.mode, 4);
				buffer.put(data.getLength(), 8);
				data.write(buffer);
			}
			return buffer.buffer;
		}
	};

	function QRBitBuffer() { this.buffer = []; this.length = 0; }
	QRBitBuffer.prototype = {
		get: function (index) { var bufIndex = Math.floor(index / 8); return ((this.buffer[bufIndex] >>> (7 - index % 8)) & 1) == 1; },
		put: function (num, length) { for (var i = 0; i < length; i++) { this.putBit(((num >>> (length - i - 1)) & 1) == 1); } },
		putBit: function (bit) { var bufIndex = Math.floor(this.length / 8); if (this.buffer.length <= bufIndex) { this.buffer.push(0); } if (bit) { this.buffer[bufIndex] |= (0x80 >>> (this.length % 8)); } this.length++; }
	};

	function _getTypeNumber(sText, nCorrectLevel) { return 4; }

	window.QRCode = QRCode;
	QRCode.CorrectLevel = QRErrorCorrectLevel;
})();
